<?php
declare(strict_types=1); namespace Neok\Pay\Resources; use Neok\Pay\Client; use Neok\Pay\DTO\{Checkout,CreateCheckoutRequest}; use Neok\Pay\Exceptions\ApiException;
final readonly class Checkouts { public function __construct(private Client $client){} public function create(CreateCheckoutRequest $request,string $idempotencyKey): Checkout { if($idempotencyKey==='')throw new \InvalidArgumentException('An idempotency key is required.');$response=$this->client->request('POST','checkouts',$request->toArray(),['Idempotency-Key'=>$idempotencyKey]);if($response->getStatusCode()!==200&&$response->getStatusCode()!==201)$this->client->parser()->error($response);$data=$this->client->parser()->json($response)['data']??null;if(!is_array($data)||!is_string($data['checkout_url']??null))throw new ApiException('NEOK Pay returned an invalid checkout response.',$response->getStatusCode());return new Checkout($this->client->parser()->payment($data),$data['checkout_url']);} }
